/* @lc app=leetcode id=1519 lang=kotlin */ class Solution { fun countSubTrees(n: Int, edges: Array<IntArray>, labels: String): IntArray = Array(n) { ArrayList<Int>() }.also { g -> edges.forEach { (a, b) -> g[a].add(b).also { g[b].add(a) } } }.let { g -> IntArray(n) { -1 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].filter { v -> par[v] == -1 && v != 0 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> Array(n) { IntArray(26) }.let { cnt -> order.reversed().forEach { v -> (++cnt[v][labels[v] - 'a']).let { if (v != 0) (0 until 26).forEach { k -> cnt[par[v]][k] += cnt[v][k] } } }.let { IntArray(n) { cnt[it][labels[it] - 'a'] } } } } } } }